"""Explicacoes das questoes do exercicio robber.

O texto esta codificado (ROT13) para nao entregar respostas a
quem so passa o olho. Para ler uma explicacao, descomente a
chamada explicar('nome') correspondente no exercicio e rode.
"""

EXPLICACOES = {
    'melhor_plano': '\nzryube_cynab - ehn = [6, 2, 2, 6]\n\nQhnf pbvfnf grz dhr fre purpnqnf rz pnqn cynab: (1) ryr qvfcnen b\nnynezr? (2) dhnagb ryr yrin?\n\n  - pnfnf 0 r 1: fnb ivmvaunf (vaqvprf pbafrphgvibf) -> NYNEZR.\n    Yrinevn 6 + 2 = 8, znf arz purtn n fre hz cynab inyvqb.\n  - pnfnf 1 r 2: gnzorz ivmvaunf -> NYNEZR. Yrinevn 2 + 2 = 4.\n  - pnfnf 0 r 2: inyvqnf (0 r 2 anb fnb pbafrphgvibf). Yrinz 6 + 2 = 8.\n  - pnfnf 0 r 3: inyvqnf (0 r 3 anb fnb pbafrphgvibf). Yrinz 6 + 6 = 12.\n\nFboenenz qbvf cynabf inyvqbf, qr 8 r qr 12. B zryube ru b qr 12: nf\npnfnf 0 r 3.\n\nReeb pbzhz: rfpbyure b cynab qnf pnfnf 0 r 1 cbe qne b znvbe ahzreb\nfrz ercnene dhr ryr ru cebvovqb. B nynezr irz cevzrveb - fb snm\nfragvqb pbzcnene dhnagvnf rager cynabf dhr wn cnffnenz arffn\npurpntrz.\n',
    'roubo_5115': '\nebhob_5115 - ehn = [5, 1, 1, 5]\n\nBf cynabf inyvqbf (frz qhnf pnfnf ivmvaunf) r b dhr pnqn hz yrin:\n\n  - pnfn 0 fbmvaun:  5\n  - pnfn 1 fbmvaun:  1\n  - pnfn 2 fbmvaun:  1\n  - pnfn 3 fbmvaun:  5\n  - pnfnf 0 r 2:     5 + 1 = 6\n  - pnfnf 0 r 3:     5 + 5 = 10   <- zryube\n  - pnfnf 1 r 3:     1 + 5 = 6\n\nErfcbfgn: 10.\n\nErcner ab dhr b zryube cynab srm: ryr CHYBH QHNF pnfnf frthvqnf (n 1\nr n 2) cnen cbqre crtne nf qhnf cbagnf.\n\nReeb pbzhz: npune dhr b pregb ru frzcer nygreane - hzn pnfn fvz, hzn\npnfn anb. Nygreanaqb n cnegve qn pnfn 0 ibpr crtn nf pnfnf 0 r 2 r\nyrin 6; nygreanaqb n cnegve qn pnfn 1 ibpr crtn nf pnfnf 1 r 3 r yrin\n6 gnzorz. Bf qbvf qnb 6, r 6 anb ru b znkvzb. N erten ru "anb cbqr\ncrtne qhnf IVMVAUNF", r anb "grz dhr crtne hzn fvz hzn anb" - chyne\nqhnf qr hzn irm ru crezvgvqb, r nf irmrf ru b dhr cntn zryube.\n',
    'roubo_35416': '\nebhob_35416 - ehn = [3, 5, 4, 1, 6]\n\nB zryube cynab ru nffnygne nf pnfnf 0, 2 r 4:\n\n    3 + 4 + 6 = 13\n\nPbasven dhr ryr ru inyvqb: 0, 2 r 4 anb grz qbvf vaqvprf pbafrphgvibf\nrager fv.\n\nErfcbfgn: 13.\n\nReeb pbzhz (b dhr b rahapvnqb nivfn): pbzrpne cryn pnfn znvf purvn r\nve qrfpraqb. N pnfn znvf purvn ru n 4, pbz 6. Crtnaqb ryn, n pnfn 3\nsvpn cebvovqn; n cebkvzn znvf purvn nvaqn crezvgvqn ru n pnfn 1, pbz\n5, r nv n pnfn 0 r n pnfn 2 svpnz cebvovqnf gnzorz. B cynab iven\n{4, 1} r yrin 6 + 5 = 11. Bamr ru zrabf dhr germr - rfpbyure frzcer b\nznvbe qvfcbaviry anb erfbyir rfgr ceboyrzn.\n\nBhgebf inyberf reenqbf dhr ncnerprz: 19 ru fbzne n ehn gbqn (vtaben b\nnynezr), r 6 ru crtne fb nf pnfnf qr vaqvpr vzcne (nf pnfnf 1 r 3).\n',
    'rouba_a_mao_1': '\nebhon_n_znb_1 - ehn = [3, 5, 4, 1, 6], pnyphyne ebhon(0)\n\nN erpbeerapvn cnen n pnfn 0 ru\n\n    ebhon(0) = znk( ebhon(1),  ehn[0] + ebhon(2) )\n\nFhofgvghvaqb b dhr sbv qnqb (ebhon(1) = 11, ebhon(2) = 10) r\nehn[0] = 3:\n\n    ebhon(0) = znk( 11,  3 + 10 ) = znk(11, 13) = 13\n\nErfcbfgn: 13. Ndhv NFFNYGNE n pnfn 0 tnaun: bf 3 ernvf qryn znvf bf\n10 qn ehn n cnegve qn pnfn 2 ongrz bf 11 qr fvzcyrfzragr chyne ryn.\n\nFboer bf bhgebf ahzrebf qnqbf: ebhon(3), ebhon(4) r ebhon(5) ANB\nragenz arfgn pbagn. Ryrf sbenz qnqbf qr cebcbfvgb - n erpbeerapvn qn\npnfn 0 byun fb qhnf pnfnf n seragr, r erpbaurpre DHNVF qbf qnqbf\nfreirz snm cnegr qb rkrepvpvb.\n\nReebf pbzhaf: fbzne ghqb dhr sbv qnqb (11 + 10 + 6 + 6 + 0 = 33);\nfbzne ebhon(1) + ebhon(2) (= 21), pbzb fr qrffr cnen chyne r nffnygne\nnb zrfzb grzcb - fnb qhnf nygreangvinf, rfpbyur-fr HZN, cbe vffb ru\nznk r anb fbzn.\n',
    'rouba_a_mao_2': '\nebhon_n_znb_2 - ehn = [1, 9, 1, 1], pnyphyne ebhon(0)\n\nZrfzn erpbeerapvn:\n\n    ebhon(0) = znk( ebhon(1),  ehn[0] + ebhon(2) )\n             = znk( 10,  1 + 1 )\n             = znk(10, 2)\n             = 10\n\nErfcbfgn: 10.\n\nErcner an qvsrerapn cnen n dhrfgnb nagrevbe: ndhv dhrz tnaun ru CHYNE\nn pnfn 0. Ryn fb grz 1 erny, r nffnygne ryn phfgn pneb - cebvor n\npnfn 1, dhr ru whfgnzragr n pnfn purvn (9 ernvf). Chyne n pnfn 0 r\nngnpne n ehn n cnegve qn pnfn 1 eraqr 10.\n\nRu cnen vffb dhr freir b znk: arz frzcer nffnygne n pnfn qn irm ru b\nzryube, r arz frzcer chyne ru b zryube. N sbezhyn grfgn nf qhnf\nbcpbrf r svpn pbz n znvbe.\n\nReeb pbzhz: nffnygne frzcer n pnfn qn irm, frz byune n bhgen bcpnb.\nVffb qn ehn[0] + ebhon(2) = 1 + 1 = 2. (An dhrfgnb nagrevbe rffr\nzrfzb reeb qnin n erfcbfgn pregn cbe fbegr, cbedhr yn nffnygne ren\nzrfzb b zryube.)\n',
    'rouba_base': '\nebhon_onfr - ehn = [1, 9, 1, 1], dhnagb inyr ebhon(7)?\n\nErfcbfgn: 0.\n\nebhon(pnfn) ru "n znvbe dhnagvn qn ehn N CNEGVE qndhryn pnfn". N ehn grz 4\npnfnf, qr vaqvpr 0 n 3. B vaqvpr 7 wn cnffbh qb svz: anb rkvfgr pnfn\narauhzn qnyv rz qvnagr, ragnb anb un b dhr ebhone, r n znvbe dhnagvn\ncbffviry ru mreb.\n\nRz pbqvtb, vffb ru rkngnzragr b pnfb-onfr:\n\n    vs pnfn >= yra(ehn):\n        erghea 0\n\nNdhv yra(ehn) ru 4, r 7 >= 4.\n\nCbe dhr vffb vzcbegn: ru rffr pnfb-onfr dhr snm n erphefnb CNENE. Frz\nryr, ebhon(7) punznevn ebhon(8), dhr punznevn ebhon(9), r nffvz cbe\nqvnagr cnen frzcer.\n\nReeb pbzhz: erfcbaqre 1, vzntvanaqb dhr b vaqvpr "qn n ibygn" r pnv\nan hygvzn pnfn. Rz Clguba, vaqvpr artngvib qn n ibygn (ehn[-1] ru n\nhygvzn pnfn), znf vaqvpr tenaqr qrznvf anb - r qr dhnydhre sbezn n\nerphefnb ndhv ahapn nprffn ehn[7]: b pnfb-onfr qribyir 0 nagrf qvffb.\n',
    'casa_mais_repetida': '\npnfn_znvf_ercrgvqn - n fnvqn qb cevag qrageb qn ebhon\n\nN erfcbfgn ru N PNFN 5.\n\nPbagnaqb nf punznqnf qr ebhon([3, 5, 4, 1, 6, 2], 0), pnfn cbe pnfn:\n\n    pnfn 0:  1 irm\n    pnfn 1:  1 irm\n    pnfn 2:  2 irmrf\n    pnfn 3:  3 irmrf\n    pnfn 4:  5 irmrf\n    pnfn 5:  8 irmrf\n\n(n pnfn 6 r n pnfn 7 gnzorz ncnerprz an fnvqn - fnb nf punznqnf dhr wn\npnrz ab pnfb-onfr, cbedhr n ehn npnon an pnfn 5.)\n\nIbpr anb cerpvfnin pbagne ghqb vffb. Onfgnin ebyne n fnvqn r ercnene\ndhr n pnfn 0 ncnerpr hzn irm fb, radhnagb n pnfn 5 ibygn b grzcb gbqb.\n\nCbe dhr ru b SVZ qn ehn dhr ncnaun znvf: n pnfn 0 ru nypnapnqn cbe hz\npnzvaub fb - n punznqn vavpvny, dhr ibpr zrfzb srm. Wn n pnfn 5 ru\nnypnapnqn cbe zhvgbf pnzvaubf qvsreragrf, cbedhr pnqn pnfn nagrf qryn\nbsrerpr qhnf pbagvahnpbrf (chyne bh nffnygne) r inevnf pbzovanpbrf\nqrffnf rfpbyunf grezvanz yn. Pnqn hz qrffrf pnzvaubf ersnm n pbagn\nvagrven qn pnfn 5, qb mreb, r frzcer pbz b zrfzb erfhygnqb - n ehn anb\nzhqbh r n pnfn anb zhqbh. Ru rffr genonyub wbtnqb sben dhr n\nzrzbvmnpnb inv zngne an cebkvzn snfr.\n\nFboer nf bhgenf nygreangvinf:\n\n  - "n pnfn 0" ru b cnycvgr vaghvgvib, r ru whfgnzragr b pbagenevb: n\n    erphefnb PBZRPN an pnfn 0, ragnb cnerpr dhr ryn ebqn b grzcb gbqb.\n    Znf pbzrpne nyv fvtavsvpn cnffne cbe ryn hzn irm fb.\n  - "n pnfn 2" ercrgr zrfzb - qhnf irmrf - znf svpn ab zrvb qb\n    pnzvaub. Dhnagb znvf cnen b svz qn ehn, znvf pnzvaubf purtnz yn.\n  - "gbqnf ncnerprenz b zrfzb ahzreb qr irmrf" anb fr fhfgragn nffvz\n    dhr ibpr pbzcnen nf qhnf cbagnf: hzn irm pbagen bvgb. Fr n fhn\n    fnvqn cnerprh havsbezr, pbasven fr b cevag sbv pbynqb pbzb\n    CEVZRVEN yvaun qb pbecb qn ebhon, r fr n yvaun\n    cevag(ebhon([3, 5, 4, 1, 6, 2], 0)) sbv zrfzb qrfpbzragnqn.\n',
    'consulta_do_memo': '\npbafhygn_qb_zrzb - b ohenpb (N), n cbagn qr pvzn\n\nN erfcbfgn ru:\n\n    vs pnfn va zrzb.xrlf():\n        erghea zrzb[pnfn]\n\nB zrzb ru hz qvpvbanevb phwn PUNIR ru n pnfn r phwb INYBE ru n erfcbfgn\nqndhryn pnfn rz qvnagr. Ragnb n cbagn qr pvzn ru: nagrf qr pbzchgne\ndhnydhre pbvfn, irwn fr rffn pnfn wn rfgn thneqnqn r, fr rfgvire,\nqribyin b dhr rfgn thneqnqb.\n\nFboer nf bhgenf nygreangvinf:\n\n  - `vs zrzb[pnfn]: erghea zrzb[pnfn]` ru b wrvgb angheny-znf-reenqb qr\n    grfgne fr n punir rkvfgr. `zrzb[pnfn]` NPRFFN b qvpvbanevb, r nprffne\n    hzn punir dhr anb rkvfgr yrinagn XrlReebe - whfgnzragr ab pnfb dhr\n    ibpr rfgn gragnaqb qrgrpgne. Dhrz grfgn cerfrapn frz nprffne ru b\n    `va zrzb.xrlf()`, dhr byun n yvfgn qr punirf rz irm qr ohfpne b inybe\n    qr hzn qrynf. (R grz hz frthaqb ceboyrzn: zrfzb dhnaqb n punir\n    rkvfgr, fr b inybe thneqnqb sbe 0, b `vs` qn snyfb r n shapnb\n    erpbzchgn n gbn.)\n  - `zrzb[pnfn] = 0` RFPERIR rz irm qr yre. Anb qribyir anqn qr ibygn,\n    ragnb anqn ru erncebirvgnqb r n shapnb pbagvahn gnb yragn dhnagb n\n    qn Snfr 3.\n  - `vs pnfn va zrzb.xrlf(): erghea pnfn` qribyir b VAQVPR qn pnfn rz irm\n    qn dhnagvn thneqnqn. ebhon_zrzb([2, 7, 9, 3, 1], 0, {}) erfcbaqrevn\n    13 rz irm qr 12 - ercner dhr reen cbe cbhpb, r anb rfpnaqnybfnzragr:\n    dhnaqb b vaqvpr ru crdhrab ryr fr qvfsnepn orz ab zrvb qnf fbznf.\n',
    'memo_nas_chamadas': '\nzrzb_anf_punznqnf - b ohenpb (O), anf qhnf punznqnf erphefvinf\n\nN erfcbfgn ru `zrzb` - b ZRFZB qvpvbanevb, ercnffnqb vagrveb.\n\nRu b cbagb gbqb qn zrzbvmnpnb: rkvfgr HZ qvpvbanevb fb, pbzcnegvyunqb\ncbe gbqn n erphefnb. Qvpvbanevb ru zhgniry, ragnb dhnaqb ibpr cnffn ryr\ncbe cnenzrgeb nf punznqnf qr qrageb zrkrz ab zrfzb qvpvbanevb dhr rfgn\nndhv sben - b dhr hzn thneqn, n bhgen rakretn.\n\nFboer nf bhgenf nygreangvinf:\n\n  - `{}` pevn hz qvpvbanevb ABIB r INMVB n pnqn punznqn. Pnqn punznqn\n    cnffn n gre hz zrzb fb qryn, dhr anfpr inmvb r zbeer ab svz -\n    avathrz pbzcnegvyun anqn pbz avathrz. N shapnb svpn rkngnzragr gnb\n    yragn dhnagb n ebhon qn Snfr 3, r genin ab grfgr qn ehn qr 90 pnfnf.\n    Ru b reeb dhr b cevag qr nivfb qndhryr grfgr abzrvn.\n  - punzne pbz qbvf nethzragbf yrinagn GlcrReebe: ebhon_zrzb sbv\n    qrsvavqn pbz gerf cnenzrgebf, r Clguba rkvtr bf gerf.\n  - `zrzb[pnfn]` cnffn b AHZREB thneqnqb rz irm qb qvpvbanevb. Nyrz qr\n    fre n pbvfn reenqn, yrinagn XrlReebe: n pnfn nvaqn anb sbv thneqnqn\n    (ru whfgnzragr vffb dhr n shapnb rfgn vaqb pbzchgne).\n',
    'guarda_no_memo': '\nthneqn_ab_zrzb - b ohenpb (P), n cbagn qr onvkb\n\nN erfcbfgn ru:\n\n    zrzb[pnfn] = znk(chyn, nffnygn)\n    erghea zrzb[pnfn]\n\nQhnf pbvfnf, arfgn beqrz: thneqr b erfhygnqb an punir qndhryn pnfn, r\nfb ragnb qribyin. Thneqne ru b dhr snm n cebkvzn punznqn pbz b zrfzb\n`pnfn` fnve cryn cbagn qr pvzn, frz erpbzchgne.\n\nFboer nf bhgenf nygreangvinf:\n\n  - `erghea znk(chyn, nffnygn)`, fbmvaub, ru n nygreangvin znvf\n    crevtbfn: ryn rfgn PBEERGN. Qribyir n erfcbfgn pregn rz gbqn\n    ragenqn, r cnffn rz gbqbf bf grfgrf crdhrabf. Fb dhr ryn anb thneqn\n    anqn, ragnb b zrzb svpn inmvb cnen frzcer r n cbagn qr pvzn ahapn\n    qvfcnen - n shapnb pbagvahn fraqb n qn Snfr 3 pbz hz cnenzrgeb n\n    znvf. Ibpr qrfpboer vffb qr qbvf wrvgbf: b nffreg dhr pbasrer dhr b\n    zrzb anb svpbh inmvb, r b grfgr qn ehn qr 90 pnfnf, dhr genin.\n  - `zrzb[pnfn] = znk(chyn, nffnygn)` frz b `erghea` thneqn pregb znf\n    anb qribyir anqn - n shapnb erfcbaqr Abar, r n pbagn qr sben iven\n    Abar + ahzreb, dhr yrinagn GlcrReebe.\n  - `zrzb[znk(chyn, nffnygn)] = pnfn` gebpn n punir cryb inybe: thneqn n\n    pnfn vaqrknqn cryn dhnagvn, dhr ru b pbagenevb qb dhr n cbagn qr\n    pvzn inv cebphene. R nvaqn qribyir b vaqvpr rz irm qn dhnagvn.\n',
    'tabela_2793': '\ngnoryn_2793 - ehn = [2, 7, 9, 3, 1]\n\nN gnoryn grz yra(ehn) + 2 = 7 pryhynf, gbqnf pbzrpnaqb rz 0:\n\n    gnoryn = [0, 0, 0, 0, 0, 0, 0]\n    #         0  1  2  3  4  5  6\n\nNf pryhynf 5 r 6 fnb b pnfb-onfr ("n ehn wn npnobh") r svpnz 0 cnen\nfrzcer. Cerrapuraqb qr genf cnen n seragr, pbz\n\n    gnoryn[pnfn] = znk( gnoryn[pnfn + 1],  ehn[pnfn] + gnoryn[pnfn + 2] )\n\n    pnfn = 4:  znk( gnoryn[5],  1 + gnoryn[6] ) = znk(0, 1 + 0) =  1\n    pnfn = 3:  znk( gnoryn[4],  3 + gnoryn[5] ) = znk(1, 3 + 0) =  3\n    pnfn = 2:  znk( gnoryn[3],  9 + gnoryn[4] ) = znk(3, 9 + 1) = 10\n    pnfn = 1:  znk( gnoryn[2],  7 + gnoryn[3] ) = znk(10, 7 + 3) = 10\n    pnfn = 0:  znk( gnoryn[1],  2 + gnoryn[2] ) = znk(10, 2 + 10) = 12\n\n    gnoryn = [12, 10, 10, 3, 1, 0, 0]\n\nN pryhyn 0 qrh 12, dhr ru n erfcbfgn qb Rkrzcyb 2 qb rahapvnqb -\npbasrer.\n\nErcner ab rzcngr rz pnfn = 1: nf qhnf bcpbrf qnb 10. Chyne n pnfn 1\neraqr bf 10 qn ehn n cnegve qn pnfn 2; nffnygne n pnfn 1 eraqr\n7 + 3 = 10 gnzorz. Dhnaqb rzcngn, gnagb snm - b znk qribyir 10 qr\ndhnydhre wrvgb.\n\nReebf pbzhaf:\n\n  - Snmre n gnoryn pbz fb 5 pryhynf (hzn cbe pnfn). Nv nf pbagnf qr\n    pnfn = 4 r pnfn = 3 cerpvfnevnz qr pryhynf dhr anb rkvfgrz. Nf qhnf\n    pryhynf n znvf ab svz fnb b pnfb-onfr, r rkvfgrz whfgnzragr cnen\n    vffb.\n  - Cerrapure qr seragr cnen genf (pnfn = 0 cevzrveb). Anb qn: gnoryn[0]\n    qrcraqr qr gnoryn[1] r gnoryn[2], dhr nvaqn rfgnevnz inmvnf.\n  - Rfperire fb nf 5 cevzrvenf pryhynf r rfdhrpre bf qbvf mrebf qb\n    svz - n dhrfgnb crqr n gnoryn vagrven, nf 7 pryhynf.\n',
    'tamanho_da_tabela': '\ngnznaub_qn_gnoryn - qr dhr gnznaub pevne n yvfgn\n\nN erfcbfgn ru `[0] * (yra(ehn) + 2)`.\n\nFnb yra(ehn) pryhynf cnen nf pnfnf qr ireqnqr, ZNVF QHNF ab svz cnen b\npnfb-onfr "n ehn wn npnobh". Nf qhnf svpnz inyraqb 0 cnen frzcer, r\nrkvfgrz cnen dhr n pbagn qn erpbeerapvn frzcer graun b dhr yre.\n\nIrwn cbe dhr qhnf, r anb hzn. N pbagn qn HYGVZN pnfn (vaqvpr\nyra(ehn) - 1) yr `gnoryn[pnfn + 2]`, dhr ru b vaqvpr yra(ehn) + 1. Cnen\nrffr vaqvpr rkvfgve, n yvfgn cerpvfn gre yra(ehn) + 2 pryhynf.\n\nFboer nf bhgenf nygreangvinf:\n\n  - `[0] * yra(ehn)` ru hzn pryhyn cbe pnfn, dhr ru b cnycvgr angheny.\n    B znvbe vaqvpr inyvqb cnffn n fre yra(ehn) - 1, r n pbagn qn hygvzn\n    pnfn rfgbhen VaqrkReebe nb gragne yre `gnoryn[pnfn + 2]`.\n  - `[0] * (yra(ehn) + 1)` grz hzn pryhyn n znvf fb. Nqvn b ceboyrzn\n    rz hz cnffb r rfgbhen qb zrfzb wrvgb, gnzorz an hygvzn pnfn.\n  - `[]` frevn zbagne n yvfgn pbz nccraq pbasbezr naqn. Anb shapvban\n    ndhv: `gnoryn[pnfn] = ...` rkvtr dhr n cbfvpnb wn rkvfgn, r b\n    cerrapuvzragb inv qr genf cnen n seragr, ragnb n cevzrven cbfvpnb n\n    erprore inybe ru hzn qnf hygvznf.\n',
    'laco_da_tabela': '\nynpb_qn_gnoryn - b ynpb qr genf cnen n seragr\n\nN erfcbfgn ru `sbe pnfn va enatr(yra(ehn) - 1, -1, -1)`.\n\nBf gerf ahzrebf qb enatr fnb, arfgn beqrz: baqr PBZRPNE, baqr CNENE\n(frz vapyhve) r qr dhnagb rz dhnagb NAQNE.\n\n  - pbzrpn rz yra(ehn) - 1, n hygvzn pnfn qn ehn;\n  - naqn qr -1 rz -1, bh frwn, cnen genf;\n  - cnen NAGRF qr -1, r ru cbe vffb dhr b frthaqb ahzreb ru -1 r anb 0.\n\nRffr hygvzb cbagb ru b dhr crtn dhnfr gbqb zhaqb. `enatr` AHAPN vapyhv\nb ahzreb qr cnenqn. Fr ibpr dhre dhr n pnfn 0 rager ab ynpb, n cnenqn\ngrz dhr fre b ahzreb NAGRF qryn, dhr ru -1.\n\nFboer nf bhgenf nygreangvinf:\n\n  - `enatr(yra(ehn) - 1, 0, -1)` ru b reeb znvf cebiniry qr gbqbf, r b\n    znvf fvyrapvbfb: cnene rz 0 fvtavsvpn cnene NAGRF qb 0, ragnb n pnfn\n    0 ahapn ru cerrapuvqn. `gnoryn[0]` svpn pbz b mreb qb vavpvb, r n\n    shapnb qribyir 0 cnen dhnydhre ehn. Anb rfgbhen reeb arauhz - fb\n    erfcbaqr reenqb.\n  - `enatr(yra(ehn))` crepbeer qr SERAGR cnen genf. Pnqn pryhyn frevn\n    pbzchgnqn n cnegve qr pryhynf n qvervgn dhr nvaqn anb sbenz\n    cerrapuvqnf (nvaqn inyrz 0), ragnb nf pbagnf fnrz reenqnf. Gnzorz\n    frz reeb arauhz: b cvbe gvcb qr oht.\n  - `enatr(yra(ehn), 0, -1)` pbzrpn rz yra(ehn), dhr anb ru pnfn qr\n    ireqnqr - ru hzn qnf pryhynf qb pnfb-onfr. An cevzrven ibygn ryn\n    gragn yre `ehn[yra(ehn)]` r rfgbhen VaqrkReebe.\n',
    'dentro_do_laco': '\nqrageb_qb_ynpb - n erpbeerapvn yraqb qn gnoryn\n\nN erfcbfgn ru:\n\n    gnoryn[pnfn] = znk(gnoryn[pnfn + 1], ehn[pnfn] + gnoryn[pnfn + 2])\n\nRu n ZRFZN erpbeerapvn qn Snfr 2, yrgen cbe yrgen - n havpn qvsrerapn\nru dhr baqr nagrf univn hzn punznqn `ebhon(ehn, pnfn + 1)` ntben un hzn\nyrvghen `gnoryn[pnfn + 1]`. Nf qhnf bcpbrf pbagvahnz fraqb: chyne n\npnfn qn irm, bh nffnygne ryn r fnygne cbe pvzn qn ivmvaun.\n\nFboer nf bhgenf nygreangvinf:\n\n  - n irefnb pbz `pnfn - 1` r `pnfn - 2` ru n erpbeerapvn qn bhgen\n    sbezhynpnb cbffviry qb ceboyrzn, n dhr byun n HYGVZN pnfn rz irm qn\n    cevzrven. Ryn anb pbzovan pbz rfgn gnoryn: pbzb b ynpb naqn qr genf\n    cnen n seragr, nf pryhynf n RFDHREQN nvaqn anb sbenz cerrapuvqnf r\n    inyrz 0. R byun b qrgnyur pehry: dhnaqb pnfn ru 0, `gnoryn[pnfn - 1]`\n    iven `gnoryn[-1]`, r rz Clguba vaqvpr artngvib anb rfgbhen - ryr qn\n    n ibygn r yr n hygvzn pryhyn. B reeb anb ncnerpr pbzb reeb.\n  - `ehn[pnfn] + gnoryn[pnfn + 2]` rfdhrpr n bcpnb qr CHYNE: nffnygn\n    frzcer. Ru b zrfzb reeb qb ebhon_n_znb_2 qn Snfr 2, r qn b zrfzb\n    gvcb qr erfcbfgn ehvz - rz [1, 9, 1, 1] qribyir 2 rz irm qr 10,\n    cbedhr vafvfgr rz crtne b 1 qn pnfn 0 r creqr b 9 qn pnfn 1.\n  - `znk(ehn[pnfn], gnoryn[pnfn + 1])` rfdhrpr qr FBZNE b erfgb qn ehn:\n    pbzcnen n dhnagvn qr hzn pnfn fbmvaun pbz b erfhygnqb qb ivmvaub, r\n    npnon qribyiraqb fb n znvbe pnfn qn ehn. Rz [1, 2, 3, 1] qn 3 rz irm\n    qr 4.\n',
    'o_que_devolver': '\nb_dhr_qribyire - baqr rfgn n erfcbfgn\n\nN erfcbfgn ru `erghea gnoryn[0]`.\n\n`gnoryn[pnfn]` thneqn n znvbe dhnagvn qn ehn N CNEGVE qn pnfn `pnfn`.\nN ehn vagrven pbzrpn an pnfn 0, ragnb n erfcbfgn qb ceboyrzn gbqb ru\n`gnoryn[0]` - n cevzrven pryhyn, n hygvzn n fre cerrapuvqn.\n\nIbpr wn gvaun pbasrevqb vffb n znb: ab gnoryn_2793 n pryhyn 0 qrh 12,\ndhr ru n erfcbfgn qb Rkrzcyb 2 qb rahapvnqb.\n\nFboer nf bhgenf nygreangvinf:\n\n  - `gnoryn[yra(ehn) - 1]` ru n pryhyn qn HYGVZN pnfn qn ehn, bh frwn\n    "b zryube dhr qn cen snmre byunaqb fb n hygvzn pnfn". Rz\n    [2, 7, 9, 3, 1] vffb ru 1, r anb 12.\n  - `gnoryn[-1]` ru n hygvzn pryhyn qn YVFGN, dhr ru hzn qnf qhnf qb\n    pnfb-onfr. Ryn inyr 0 cnen gbqn ehn, frzcer.\n  - `gnoryn` qribyir n yvfgn vagrven rz irm qb ahzreb. Dhrz punzbh dhre\n    hzn dhnagvn, anb n gnoryn.\n',
}
